steps.script:
$o=@{project='ttendencias';action='none'}
try{
 $active=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'" -ErrorAction Stop|Where-Object{[string]$_.CommandLine -match 'TT-Editorial-Guard[.]js|Ejecutar[.]js'})
 $t=Get-ScheduledTask -TaskName 'TTendencias Local' -ErrorAction Stop
 $i=Get-ScheduledTaskInfo -TaskName $t.TaskName -ErrorAction Stop
 $o.last=[string]$i.LastRunTime;$o.result=$i.LastTaskResult;$o.state=[string]$t.State
 if($active.Count -gt 0){$o.action='deferred_active_runner'}
 elseif([string]$t.State -ne 'Ready'){$o.action='deferred_task_not_ready'}
 else{Start-ScheduledTask -TaskName $t.TaskName -ErrorAction Stop;$o.action='requested'}
}catch{$o.action='error';$o.error=$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
